def _backfill_from_results_json() -> None:
    """Copy existing denormalised blobs into the new table.

    Without this, every search recorded before this migration would show an
    empty result list -- the data would still be sitting in ``results_json``
    but nothing would read it any more.
    """
    import json

    conn = op.get_bind()
    rows = conn.execute(
        sa.text("SELECT id, results_json FROM search_history WHERE results_json IS NOT NULL")
    ).fetchall()

    inserts = []
    for search_id, blob in rows:
        if isinstance(blob, str):
            try:
                blob = json.loads(blob)
            except (TypeError, ValueError):
                continue
        if not isinstance(blob, dict):
            continue
        for position, movie in enumerate(blob.get("results") or []):
            if not isinstance(movie, dict):
                continue
            imdb_id = (movie.get("imdb_id") or "")[:20]
            if not imdb_id:
                continue
            inserts.append(
                {
                    "search_id": search_id,
                    "position": position,
                    "imdb_id": imdb_id,
                    "title": (movie.get("title") or "")[:512],
                }
            )

    if inserts:
        conn.execute(
            sa.text(
                "INSERT INTO search_results (search_id, position, imdb_id, title) "
                "VALUES (:search_id, :position, :imdb_id, :title)"
            ),
            inserts,
        )


